import numpy as np,pandas as pd
from scipy.signal import savgol_filter
def arx(files,dec,na,nb,ncs,extra=False):
    Xs=[];ys=[]
    for f in files:
        d=pd.read_csv(f).iloc[::dec].reset_index(drop=True)
        Q=d.reactive_power_pu.values; V=d.voltage_pu.values; Vs=d.voltage_setpoint_pu.values; th=d.bus_angle_rad.values
        n=len(Q); m=max(na,nb,ncs)
        cols=[]
        for i in range(1,na+1): cols.append(Q[m-i:n-i])
        for j in range(0,nb+1): cols.append(V[m-j:n-j])
        for j in range(0,ncs+1): cols.append(Vs[m-j:n-j])
        cols.append(np.ones(n-m))
        if extra:
            cols.append(th[m:n]); 
        Xs.append(np.column_stack(cols)); ys.append(Q[m:])
    X=np.vstack(Xs); y=np.concatenate(ys)
    b=np.linalg.lstsq(X,y,rcond=None)[0]
    r=y-X@b
    return b, np.sqrt(np.mean(r**2))
